// One colour, one motion and one tone per kind of notification.
//
// `section` names a range of frames in animations/clawd.anim and `tone` a file in sounds/; both
// are generated by tools/assets.py, whose KINDS and TONES tables this one has to agree with.

export interface Kind {
  /** #RRGGBBAA, for the LED; the mascot's colour is baked into its section. */
  color: string;
  section: string;
  /** Undefined for a kind that arrives silently. */
  tone?: string;
  /** How long it stays up when nothing is waiting behind it. */
  seconds: number;
}

const KINDS: Record<string, Kind> = {
  perm: { color: "#FF8800FF", section: "perm", tone: "perm", seconds: 10 },
  question: { color: "#AA55FFFF", section: "question", tone: "question", seconds: 10 },
  ask: { color: "#00AAFFFF", section: "ask", tone: "ask", seconds: 10 },
  done: { color: "#00FF66FF", section: "done", tone: "done", seconds: 8 },
  agent: { color: "#99FF33FF", section: "agent", tone: "agent", seconds: 8 },
  error: { color: "#FF2244FF", section: "error", tone: "error", seconds: 10 },
  hello: { color: "#D97757FF", section: "hello", seconds: 5 },
};

const FALLBACK: Kind = KINDS["ask"]!;

/** A kind this build has never heard of is shown as a plain "your turn". */
export function kindOf(name: string): Kind {
  return KINDS[name] ?? FALLBACK;
}

/** Kinds that end a turn: the moment the usage numbers are worth a look. */
export function showsUsage(name: string): boolean {
  return name === "done" || name === "agent";
}
